import React, { useState } from 'react';
import { View, Image, StyleSheet, Text, Pressable } from 'react-native';

const Outdoor_CLG = ({ route, navigation }) => {
    const [rowGap, setRowGap] = useState(10);
    const [colGap, setColGap] = useState(10);

    const renderImages = () => {
        const images = [
            'basketBallGame.png',
            'CricketGame.png',
            'TennisGame.png',
            'FootballGame.png',
            'BadmintionGame.png',
            'VolleyBallGame.png',
            'ArcheryGame.png',
        ];

        return images.map((imageName, index) => (
            <Image
                key={index}
                style={styles.appdim}
                resizeMode='contain'
                source={require(`/assets/${imageName}`)}
            />
        ));
    };

    return (
        //{renderImages()}
        <View style={styles.container}>
            <View style={styles.navbuttoncontainer}>
                <Text style={{ color: 'white', fontSize: 50 }}>Which Sport?</Text>
            </View>
            <View style={styles.orangebutton}>
                <Text style={{ color: 'black', fontSize: 40 }}>College: Indoor</Text>
            </View>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View   style={styles.imageContainer}
                        source={require('/assets/basketBallGame.png')}>
                      
                </View>
                <View   style={styles.imageContainer}
                        source={require('/assets/basketBallGame.png')}>
                    
                    
                </View>
                <View   style={styles.imageContainer}
                        source={require('/assets/basketBallGame.png')}>
                    
                    
                </View>
                <View   style={styles.imageContainer}
                        source={require('/assets/basketBallGame.png')}>
                    
                    
                </View>
                <View   style={styles.imageContainer}
                        source={require('/assets/basketBallGame.png')}>
                    
                    
                </View>
            </Pressable>
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: 'black',
        
    },
    navbuttoncontainer: {
        justifyContent: 'center',
        alignItems: 'center',
        height: 30,
    },
    orangebutton: {
        justifyContent: 'flex-start',
        alignItems: 'center',
        width: 200,
        height: 100,
        borderRadius: 100,
        borderWidth: 20,
    },
    imageContainer: {
        flexDirection: 'row', // Arrange the images in a row
        flexWrap: 'wrap',    // Allow wrapping to the next row
        justifyContent: 'center',
        height: 300,
        width: 400 // Align the row at the center
    },
    appdim: {
        height: 300, // Adjust the height and width based on your requirements
        width: 200,
        margin: 50,   // Add margin between images
    },
});

export default Outdoor_CLG;
